/**
 * `--dry-run`: change nothing, show what the command would do. The CLI
 * dispatcher turns this on for one command run. HTTP clients call
 * {@link stopIfDryRun} before each request: reads still go out, so auth,
 * team, and state checks run, and the first request that would change
 * state throws {@link DryRunStop} instead. The dispatcher prints it.
 */
/** The request that a dry run stopped. Its body has secret values redacted. */
export class DryRunStop extends Error {
    constructor(request) {
        super(`Dry run: would send ${request.method} ${request.path}`);
        this.request = request;
        this.name = "DryRunStop";
    }
}
let active = false;
let stopped;
/** On for the duration of one `--dry-run` command. Either way, forgets the last stop. */
export function setDryRun(on) {
    active = on;
    stopped = undefined;
}
/**
 * The stop this run threw, even when a command caught it and returned an
 * exit code. The dispatcher prints it, so a catch-all in a command cannot
 * turn a dry run into a failure.
 */
export function takeDryRunStop() {
    const stop = stopped;
    stopped = undefined;
    return stop;
}
export function dryRunActive() {
    return active;
}
const READ_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);
/** Throw {@link DryRunStop} for a request that would change state during a dry run. */
export function stopIfDryRun(request) {
    if (active && !READ_METHODS.has(request.method.toUpperCase())) {
        stopped = new DryRunStop({ ...request, body: redactSecrets(request.body) });
        throw stopped;
    }
}
// Keys whose values are credentials or secret material: `value` (secret
// bodies), and any key ending in token, secret, password, apiKey, or
// privateKey. `secretNames` and similar name lists stay readable.
const SECRET_KEY = /^value$|token$|secret$|password$|apikey$|privatekey$/i;
/** A copy of `value` with secret-looking fields replaced by "[redacted]". */
export function redactSecrets(value) {
    if (Array.isArray(value)) {
        return value.map((item) => redactSecrets(item));
    }
    if (value === null || typeof value !== "object") {
        return value;
    }
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [
        key,
        SECRET_KEY.test(key) && item !== undefined && item !== null
            ? "[redacted]"
            : redactSecrets(item),
    ]));
}
